    {226953,"Virtuous Wraps",0,6,60,3,0,0,0,1675,0,3,0,8,11,10,0,0,0}, {272571,"Premier Legionnaire's Satin Bracers",0,6,60,4,0,0,0,0,0,2,2,12,10,0,0,0,0},
    {272822,"Premier Knight-Captain's Voidcloth Bracers",0,6,60,4,0,0,0,0,0,1,1,12,10,0,0,0,0}, {273425,"Premier Knight-Captain's Mooncloth Bracers",0,6,60,4,0,0,0,0,0,1,1,18,12,0,0,0,0},
    {273430,"Premier Legionnaire's Silken Bracers",0,6,60,4,0,0,0,0,0,2,2,18,12,0,0,0,0},
  },
}
-- Holy Math is for priests only: another class leaves the rows unread (and lets them go)
local class = UnitClass and select(2, UnitClass("player"))
if ns and class and class ~= "PRIEST" then D.rows = nil; return D end
local SLOTS = { "head", "neck", "shoulder", "back", "chest", "wrist", "hands", "waist", "legs", "feet", "finger", "trinket", "twohand", "mainhand", "offhand", "wand" }
local PROFS = { "", "Alchemy", "Blacksmithing", "Enchanting", "Engineering", "Herbalism", "Inscription", "Jewelcrafting", "Leatherworking", "Mining", "Skinning", "Tailoring" }
-- the rows as tables, once at load
D.items = {}
for i, r in ipairs(D.rows) do
  local stats = {}
  for j, k in ipairs({ "healing", "int", "spirit", "mp5", "critR", "hasteR" }) do
    if r[13 + j] ~= 0 then stats[k] = r[13 + j] end
  end
  local it = { id = r[1], name = r[2], key = r[3] ~= 0 and (r[1] .. ":" .. r[3]) or tostring(r[1]),
    suffix = r[3] ~= 0 and (r[2]:match(" (of [%a' ]+)$") or "") or "", slot = SLOTS[r[4]], lvl = r[5], q = r[6],
    unique = r[7] == 1, use = r[8] == 1, limit = r[9], set = r[10], setName = D.setNames[r[10]] or "",
    prof = PROFS[r[11] + 1], pvp = { A = r[13] % 2 == 1, H = r[13] >= 2 }, stats = stats, fx = r[20] }
  if r[12] % 2 == 1 then it.A = true end
  if r[12] >= 2 then it.H = true end
  D.items[i] = it
end
D.rows = nil
D.byKey = {}
for _, it in ipairs(D.items) do D.byKey[it.key] = it end
if ns then ns.GearData = D end
return D
